# Limit: 5 requests per second. Compare fixed window and token bucket.
LIMIT = 5

class FixedWindow:
    def __init__(self):
        self.window, self.count = -1, 0
    def allow(self, t):
        w = int(t)                        # which whole second are we in?
        if w != self.window:
            self.window, self.count = w, 0
        if self.count < LIMIT:
            self.count += 1
            return True
        return False

class TokenBucket:
    def __init__(self):
        self.tokens, self.last = float(LIMIT), 0.0
    def allow(self, t):
        # refill lazily from elapsed time: no timer thread needed
        self.tokens = min(LIMIT, self.tokens + (t - self.last) * LIMIT)
        self.last = t
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False

# 5 requests just before the second boundary, 5 just after
times = [0.90, 0.92, 0.94, 0.96, 0.98, 1.00, 1.02, 1.04, 1.06, 1.08]
for name, limiter in (("fixed window", FixedWindow()), ("token bucket", TokenBucket())):
    result = [limiter.allow(t) for t in times]
    print(name, "allowed", sum(result), "of", len(times), result)

# Tiny LSM tree: memtable, immutable sorted runs, tombstones, compaction
TOMB = None
MEM_LIMIT = 3

class LSM:
    def __init__(self):
        self.mem, self.runs = {}, []      # runs: newest last, each a sorted list
    def put(self, k, v):
        self.mem[k] = v                   # in a real system the WAL is appended first
        if len(self.mem) >= MEM_LIMIT:    # memtable full: flush as a sorted file
            self.runs.append(sorted(self.mem.items()))
            self.mem = {}
    def delete(self, k):
        self.put(k, TOMB)                 # deletes are writes of a tombstone
    def get(self, k):
        if k in self.mem:
            return self.mem[k]
        for run in reversed(self.runs):   # newest to oldest
            for key, v in run:
                if key == k:
                    return v
        return None
    def compact(self):
        merged = {}
        for run in self.runs:             # later runs overwrite earlier ones
            merged.update(run)
        self.runs = [sorted((k, v) for k, v in merged.items() if v is not TOMB)]

db = LSM()
for k, v in [("a", 1), ("b", 2), ("c", 3), ("a", 10), ("d", 4)]:
    db.put(k, v)
db.delete("b")
print("runs before:", db.runs, "memtable:", db.mem)
print("get a =", db.get("a"), " get b =", db.get("b"))
db.put("e", 5)
db.compact()
print("runs after compaction:", db.runs, "memtable:", db.mem)
